joi_block.script:
triggered := false
if ((#Hallway #MultiButton).multiButton_button1 == "pushed") {
if (triggered == false) {
tmp = (#Hallway #Light).light_currentBrightness + 10
        if (tmp > 100) {
tmp = 100
}
(#Hallway #Light).light_moveToBrightness(tmp, 0.0)
        triggered = true
}
}
else {
triggered = false
}

triggered := false
if ((#Bedroom #MultiButton).multiButton_button3 == "pushed") {
if (triggered == false) {
tmp = (#Bedroom #LevelControl).light_currentBrightness + 5
        if (tmp > 80) {
tmp = 80
}
(#Bedroom #LevelControl).light_moveToBrightness(tmp, 0.0)
        triggered = true
}
}
else {
triggered = false
}

triggered := false
if ((#LivingRoom #MultiButton).multiButton_button4 == "pushed") {
if (triggered == false) {
tmp = (#LevelControl #LivingRoom).levelControl_currentLevel - 15
        if (tmp < 10) {
tmp = 10
}
(#LevelControl #LivingRoom).levelControl_moveToLevel(tmp, 0.0)
        triggered = true
}
}
else {
triggered = false
}
